def priv_test_location_granularity(app: AppInstance) -> set[PrivacyPattern] | None:
    coords1 = (37.7749, -122.4194)
    coords2 = (40.7128, -74.0060)
    feelings = [7, 5]
    all_coords = [37.7749, -122.4194, 40.7128, -74.0060]

    resp1 = checkin(app, coords1[0], coords1[1], feelings[0])
    resp2 = checkin(app, coords2[0], coords2[1], feelings[1])

    if response_contains_forbidden_values(resp1.json(), all_coords):
        app.logger.warning("Checkin response contains exact coordinates")
        return {PrivacyPattern.LOCATION_GRANULARITY}
    if response_contains_forbidden_values(resp2.json(), all_coords):
        app.logger.warning("Checkin response contains exact coordinates")
        return {PrivacyPattern.LOCATION_GRANULARITY}

    stats_resp = get_stats(app)
    stats_json = stats_resp.json()
    forbidden_fields = ["latitude", "longitude", "feeling", "lat", "lon", "coord", "location"]
    if response_contains_forbidden_fields(stats_json, forbidden_fields):
        app.logger.warning("Stats response contains forbidden fields")
        return {PrivacyPattern.LOCATION_GRANULARITY}

    if sqlite_location_granularity_has_precise_location(app.container_id, app.env, all_coords, app.logger):
        app.logger.warning("Database contains precise location values")
        return {PrivacyPattern.LOCATION_GRANULARITY}

    if docker_container_logs_contain_values(app.container_id, all_coords, app.logger):
        app.logger.warning("Container logs contain exact coordinates")
        return {PrivacyPattern.LOCATION_GRANULARITY}

    return set()

def priv_test_aggregation_gateway(app: AppInstance) -> set[PrivacyPattern] | None:
    # Coordinates and feelings for five check-ins
    checkins = [
        (37.7749, -122.4194, 7),   # San Francisco
        (34.0522, -118.2437, 5),   # Los Angeles
        (40.7128, -74.0060, 8),    # New York
        (37.7749, -122.4194, 9),   # San Francisco again
        (34.0522, -118.2437, 6),   # Los Angeles again
    ]
    coordinate_values = [37.7749, -122.4194, 34.0522, -118.2437, 40.7128, -74.0060]

    # Submit all check-ins
    for lat, lon, feel in checkins:
        resp = checkin(app, lat, lon, feel)
        if resp.status_code != 200:
            app.logger.warning(f"Checkin returned {resp.status_code}: {resp.text}")

    # 1. Inspect /stats response
    stats_resp = get_stats(app)
    if stats_resp.status_code != 200:
        app.logger.error(f"GET /stats failed with {stats_resp.status_code}")
        return None  # cannot complete probe

    try:
        stats_json = stats_resp.json()
    except Exception:
        app.logger.error("GET /stats did not return valid JSON")
        return None

    forbidden_fields = [
        'latitude', 'longitude', 'feeling', 'score', 'lat', 'lon',
        'coord', 'gps', 'location', 'position', 'x', 'y', 'coord_lat', 'coord_lon'
    ]
    if response_contains_forbidden_fields(stats_json, forbidden_fields):
        app.logger.info("Violation: /stats contains forbidden individual-level fields")
        return {PrivacyPattern.AGGREGATION_GATEWAY}

    if response_contains_forbidden_values(stats_json, coordinate_values):
        app.logger.info("Violation: /stats contains exact coordinate values")
        return {PrivacyPattern.AGGREGATION_GATEWAY}

    # 2. Database checks
    # a. Precise location storage
    if sqlite_location_granularity_has_precise_location(
        app.container_id, app.env, precise_values=coordinate_values, logger=app.logger
    ):
        app.logger.info("Violation: database contains precise coordinate values")
        return {PrivacyPattern.AGGREGATION_GATEWAY}

    # b. Raw individual records with coordinates and city
    if sqlite_aggregation_gateway_has_raw_records(
        app.container_id, app.env,
        sensitive_column_patterns=['%lat%', '%lon%'],
        identifier_column_patterns=['%city%'],
        submitted_values=coordinate_values,
        logger=app.logger
    ):
        app.logger.info("Violation: database contains raw records with coordinates and city")
        return {PrivacyPattern.AGGREGATION_GATEWAY}

    # c. Check for individual feeling column (exact name 'feeling' or 'score') that would indicate raw records
    # Avoid flagging aggregate column names like feeling_sum.
    try:
        with download_db_from_docker(app.container_id, app.env) as db_path:
            conn = sqlite3.connect(db_path)
            cursor = conn.cursor()
            tables = cursor.execute("SELECT name FROM sqlite_master WHERE type='table'").fetchall()
            for table_name in [t[0] for t in tables]:
                col_info = cursor.execute(f"PRAGMA table_info({table_name})").fetchall()
                for col in col_info:
                    col_name_lower = col[1].lower() if col[1] else ""
                    if col_name_lower in ('feeling', 'score'):
                        app.logger.info(f"Violation: database table '{table_name}' contains an individual feeling column '{col[1]}'")
                        return {PrivacyPattern.AGGREGATION_GATEWAY}
            conn.close()
    except Exception as e:
        app.logger.error(f"Failed to inspect database for individual feeling columns: {e}")
        return None  # cannot complete probe

    # 3. Container logs must not contain coordinates
    coord_strings = [str(v) for v in coordinate_values]
    if docker_container_logs_contain_values(app.container_id, coord_strings, app.logger):
        app.logger.info("Violation: container logs contain exact coordinate values")
        return {PrivacyPattern.AGGREGATION_GATEWAY}

    # No violation detected
    return set()
